package com.primehr.learningdevelopment.participation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;
@Entity @Table(name="ld_training_order_participant",uniqueConstraints=@UniqueConstraint(name="uk_ld_training_order_participant",columnNames={"agency_id","training_order_id","employee_id"}))
public class LdTrainingOrderParticipant extends RspAuditedEntity {@Column(name="training_order_id",nullable=false,length=36)private String trainingOrderId;@Column(name="enrollment_id",nullable=false,length=36)private String enrollmentId;@Column(name="enrollment_version",nullable=false)private long enrollmentVersion;@Column(name="enrollment_fingerprint",nullable=false,length=64)private String enrollmentFingerprint;@Column(name="employee_id",nullable=false)private Long employeeId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Column(name="employee_name",nullable=false,length=300)private String employeeName;@Column(name="appointment_id",nullable=false)private Long appointmentId;@Column(name="employee_fingerprint",nullable=false,length=64)private String employeeFingerprint;@Column(name="enrollment_status",nullable=false,length=20)private String enrollmentStatus;@Column(name="display_order",nullable=false)private int displayOrder;protected LdTrainingOrderParticipant(){}public LdTrainingOrderParticipant(String agency,String order,LdEnrollment e,String fingerprint,int display){super(agency);trainingOrderId=requiredText(order,"trainingOrderId");if(e==null||e.getStatus()!=LdEnrollment.Status.CONFIRMED)throw new IllegalArgumentException("Training Order participant must have a confirmed enrollment");enrollmentId=e.getId();enrollmentVersion=e.getVersion();enrollmentFingerprint=requiredText(fingerprint,"enrollmentFingerprint");employeeId=e.getEmployeeId();employeeNo=e.getEmployeeNo();employeeName=e.getEmployeeName();appointmentId=e.getAppointmentId();employeeFingerprint=e.getEmployeeFingerprint();enrollmentStatus=e.getStatus().name();if(display<1)throw new IllegalArgumentException("displayOrder must be positive");displayOrder=display;}public String getTrainingOrderId(){return trainingOrderId;}public String getEnrollmentId(){return enrollmentId;}public long getEnrollmentVersion(){return enrollmentVersion;}public String getEnrollmentFingerprint(){return enrollmentFingerprint;}public Long getEmployeeId(){return employeeId;}public String getEmployeeNo(){return employeeNo;}public String getEmployeeName(){return employeeName;}public Long getAppointmentId(){return appointmentId;}public String getEmployeeFingerprint(){return employeeFingerprint;}public String getEnrollmentStatus(){return enrollmentStatus;}public int getDisplayOrder(){return displayOrder;}}
